cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('FS-Filters.ipynb', as_version=4)
print('cells', len(nb.cells))
for i,c in enumerate(nb.cells):
    if c.cell_type=='markdown':
        txt=' '.join(c.source.split())
        if 'accuracy' in txt.lower() or 'gain' in txt.lower() or 'filter' in txt.lower():
            print('MD',i,txt[:300])
    else:
        src=c.source
        if 'accuracy' in src.lower() or 'gain' in src.lower() or 'chi' in src.lower():
            print('CODE',i,src[:500])
