python - <<'PY'
import nbformat, json
nb=nbformat.read('/results/FS-Filters.executed.ipynb', as_version=4)
for idx in [7,8,10,13,17,19,22,23]:
    c=nb.cells[idx]
    print('\nCELL',idx,c.cell_type)
    if c.cell_type=='code':
        for out in c.get('outputs',[]):
            if out.output_type=='execute_result':
                print('EXEC',out['data'].get('text/plain',''))
            elif out.output_type=='stream':
                print('STREAM',out['text'])
            elif out.output_type=='error':
                print('ERROR',out['ename'],out['evalue'])
